# Deterministic shipping-time hardening for Windows session identity.
function Convert-RouterVPNSessionMutationText { param([string]$Source,[object[]]$Pairs,[string]$Label) $Source=$Source.Replace("`r`n","`n").Replace("`r","`n");foreach($Pair in $Pairs){$Old=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String([string]$Pair[0]));$New=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String([string]$Pair[1]));if(-not$Source.Contains($Old)){throw "$Label session-mutation source contract drifted."};$Source=$Source.Replace($Old,$New)};return $Source }
